package shed;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.awt.image.*;import javax.swing.*;import javax.imageio.ImageIO;
public class LiveCodeTaskProbe {
 static Texteditor editor;static Path output,project;static final List<Map<String,Object>> events=new ArrayList<>();static final Set<String> observed=new HashSet<>();static final java.util.concurrent.atomic.AtomicReference<Throwable> failure=new java.util.concurrent.atomic.AtomicReference<>();
 static <T>T ui(Callable<T> c)throws Exception{FutureTask<T> t=new FutureTask<>(c);SwingUtilities.invokeAndWait(t);return t.get();}
 static void observe()throws Exception{var area=editor.writingArea;var b=editor.getCurrentBuffer();String path=b==null||b.getFilePath()==null?"":project.relativize(Path.of(b.getFilePath())).toString();String activity=Objects.toString(area.getClientProperty("shed.agentActivity"),"");String animation=Objects.toString(area.getClientProperty("shed.agentAnimation"),"");String direction=Objects.toString(area.getClientProperty("shed.agentDirection"),"");String key=path+"|"+activity+"|"+animation;
  if((!activity.isEmpty()||!animation.isEmpty())&&observed.add(key)&&events.size()<18){events.add(Map.of("path",path,"activity",activity,"animation",animation,"direction",direction,"epoch_ms",System.currentTimeMillis()));Files.writeString(output.resolve("events.json"),MiniJson.stringify(events));if(events.size()<=12){var r=editor.getRootPane();var image=new BufferedImage(r.getWidth(),r.getHeight(),BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{r.paint(g);}finally{g.dispose();}ImageIO.write(image,"png",output.resolve("event-"+events.size()+".png").toFile());}System.out.println("OBSERVED "+path+" "+activity+" "+animation);System.out.flush();}
 }
 public static void main(String[] args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{failure.set(e);e.printStackTrace();});project=Path.of(args[0]).toRealPath();output=Path.of(args[1]).toRealPath();long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(420);
  try{editor=ui(()->new Texteditor(new String[]{project.toString()}));while(ui(()->editor.stagedStartupPending)){if(System.nanoTime()>deadline)throw new IllegalStateException("Startup timeout");Thread.sleep(50);}ui(()->{editor.setTitle("Shed — Live Codex: real theme-import fix");editor.setSize(1400,900);editor.workspaceController.addFolder(project,true);editor.treeGitController.showFileTree(project.toString());editor.activateEditorPane(editor.resolveTreeContentPaneForOpen());editor.hideToolWindow();editor.setMode(EditorMode.INSERT);editor.toFront();editor.handleAgentCommand("api start control");editor.toolWindowHost.watchAgentChanges("start","Codex");return null;});
  long ready=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(25);while(!ui(()->editor.visualAttachment()!=null&&Boolean.TRUE.equals(editor.toolWindowHost.watchAgentChanges("state","Codex").get("ready")))){var state=ui(()->editor.toolWindowHost.watchAgentChanges("state","Codex"));if(!Objects.toString(state.get("error"),"").isEmpty())throw new IllegalStateException("Watch admission: "+state.get("error"));if(System.nanoTime()>ready)throw new IllegalStateException("Attachment not ready");Thread.sleep(100);}
  String descriptor=ui(()->editor.visualAttachment().descriptor().toString());Files.writeString(output.resolve("ready.json"),MiniJson.stringify(Map.of("descriptor",descriptor,"project",project.toString())));
  while(!Files.exists(output.resolve("stop"))&&System.nanoTime()<deadline&&ui(()->editor.isDisplayable())){ui(()->{observe();return null;});Thread.sleep(120);}if(failure.get()!=null)throw new AssertionError(failure.get());Files.writeString(output.resolve("result.json"),MiniJson.stringify(Map.of("state","PASS","events",events.size(),"reading",events.stream().anyMatch(e->e.get("activity").toString().contains("reading")),"editing",events.stream().anyMatch(e->!e.get("animation").toString().isEmpty()))));
  }catch(Throwable e){e.printStackTrace();Files.writeString(output.resolve("result.json"),MiniJson.stringify(Map.of("state","FAIL","error",e.toString())));}finally{if(editor!=null)ui(()->{editor.shutdownRecoveryJournalScheduling();editor.shutdownSyntaxUi();editor.shutdownLspScheduling();editor.asyncJobService.shutdownNow();editor.dispose();return null;});}System.exit(failure.get()==null?0:1);
 }
}